use super::*;
use semio_framework_value::ErasedSnapshotRetirement;
use semio_framework_value::native_decoding::{NativeDecodeAllocation,NativeDecodeAllocationPort,NativeDecodeRetirementRecipient};
fn observe<T>(operation:impl FnOnce()->T)->(T,usize,usize){semio_framework_trace_memory_testing::observe_backing(operation)}
fn hex(value:&str)->Vec<u8>{value.as_bytes().chunks_exact(2).map(|pair|u8::from_str_radix(std::str::from_utf8(pair).unwrap(),16).unwrap()).collect()}
fn receipt(owner:&mut RetainedHistoryTransitionPayloadValidation,g:RetainedCloneGrant){let(issued,p)=owner.take_receipt().unwrap();assert_eq!(issued,g);assert!(p.fits(g));assert_eq!((p.retained_capacity_bytes,p.released_bytes),(0,0));}
#[test]fn original_history_transition_payload_native_preserves_all_canonical_semantic_refusals_without_cold_owners(){
 let policy:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let law:serde_json::Value=serde_json::from_str(include_str!("../../../../../../../../../🔨️modules/📡️replication/🔗️causal/🧪️tests/🧫️fixtures/🧫️history-transition/🔣️.json")).unwrap();let limits:HistoryReadLimits=serde_json::from_value(policy["limits"].clone()).unwrap();let control_limit=policy["control"]["maximumAllocationBytes"].as_u64().unwrap()as usize;let axes=&policy["grant"];let n=|key:&str|axes[key].as_u64().unwrap()as usize;let g=RetainedCloneGrant{maximum_items:n("items"),maximum_copy_bytes:n("copyBytes"),maximum_capacity_bytes:n("capacityBytes"),maximum_release_bytes:n("releaseBytes"),maximum_depth:n("depth")};
 for row in law["cases"].as_array().unwrap(){let bytes=hex(row["payloadHex"].as_str().unwrap());let accepted=row["expect"]["outcome"].as_str().unwrap()=="accepted";assert_eq!(protocol::decode_history_transition(&bytes).is_ok(),accepted,"{}",row["id"]);for cancellation in[0,1,7,17,100000]{let mut allocation=|_:NativeDecodeAllocation|->Result<(),ValueError>{panic!("original transition grammar requested native allocation")};let port:&mut NativeDecodeAllocationPort<'_>=&mut allocation;let mut callback=|_|true;let mut retirement=NativeDecodeRetirementRecipient::new();let mut control=NativeDecodeControl::new_forwarded(control_limit,&mut callback,port);control.install_retirement_recipient(&mut retirement).unwrap();
 for denied in[RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_depth:0,..g}]{let(owner,born,released)=observe(||RetainedHistoryTransitionPayloadValidation::admit(&bytes,limits,&control,denied).unwrap());assert!(owner.is_none());assert_eq!((born,released),(0,0));}
 let(owner,born,released)=observe(||RetainedHistoryTransitionPayloadValidation::admit(&bytes,limits,&control,g).unwrap());assert_eq!((born,released),(0,0));let mut owner=owner.unwrap();receipt(&mut owner,g);let changed=bytes.clone();if !bytes.is_empty(){let(result,born,released)=observe(||owner.step(&changed,&mut control,g));assert!(result.is_err());assert_eq!((born,released),(0,0));assert!(owner.receipt().is_none());}let mut foreign_callback=|_|true;let mut foreign=NativeDecodeControl::new(control_limit,&mut foreign_callback);let(result,born,released)=observe(||owner.step(&bytes,&mut foreign,g));assert!(result.is_err());assert_eq!((born,released),(0,0));drop(foreign);
 let mut refused=false;for _ in 0..cancellation{if owner.is_ready(){break}let d=owner.demands(&bytes,&control,g.maximum_copy_bytes).unwrap();for denied in[RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_depth:0,..g},RetainedCloneGrant{maximum_copy_bytes:0,..g}]{if denied.maximum_copy_bytes==0&&d.copy_bytes==0{continue}let before=owner.consumed_end();let(step,born,released)=observe(||owner.step(&bytes,&mut control,denied).unwrap());assert_eq!(step,RetainedHistoryTransitionPayloadValidationStep::Blocked);assert_eq!((born,released),(0,0));assert_eq!(owner.consumed_end(),before);assert!(owner.receipt().is_none());}let(result,born,released)=observe(||owner.step(&bytes,&mut control,g));assert_eq!((born,released),(0,0));receipt(&mut owner,g);match result{Ok(step)=>assert_ne!(step,RetainedHistoryTransitionPayloadValidationStep::Blocked),Err(_)=>{refused=true;break}}}
 if cancellation==100000{assert_eq!(refused,!accepted,"{}",row["id"]);if accepted{assert!(owner.is_ready(),"{}",row["id"]);let mut validated=None;let(moved,born,released)=observe(||owner.take_validated_into(&bytes,&control,&mut validated,g).unwrap());assert!(moved);assert_eq!((born,released),(0,0));receipt(&mut owner,g);assert!(validated.as_ref().unwrap().validates_original(&bytes,&control));if !bytes.is_empty(){assert!(!validated.as_ref().unwrap().validates_original(&changed,&control))}drop(validated);}}
 if !owner.terminal_is_empty(){owner.cancel();let(step,born,released)=observe(||owner.close_step(&bytes,&control,g).unwrap());assert_eq!(step,RetainedHistoryTransitionPayloadValidationStep::Closed);assert_eq!((born,released),(0,0));receipt(&mut owner,g);}assert!(owner.terminal_is_empty());let(_,born,released)=observe(||drop(owner));assert_eq!((born,released),(0,0));assert_eq!(control.owned_bytes(),0);drop(control);assert!(retirement.terminal_is_empty());
 }}
}
